using System.Text.Json;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals.Tests.Quality;

public class QualityTests
{
    private static readonly string GoldenPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");

    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNameCaseInsensitive = true
    };

    public static IEnumerable<object[]> GoldenCases()
    {
        var json = File.ReadAllText(GoldenPath);
        var cases = JsonSerializer.Deserialize<List<GoldenCase>>(json, JsonOptions)
            ?? throw new InvalidOperationException("Failed to deserialize golden.json");

        foreach (var c in cases)
        {
            yield return new object[] { c.Id, c };
        }
    }

    [Theory]
    [MemberData(nameof(GoldenCases))]
    public async Task EvaluateQuality(string id, GoldenCase goldenCase)
    {
        // Arrange: invoke the agent under test with the golden input
        var response = await InvokeAgentAsync(goldenCase.UserMessage);

        // Act: evaluate the response against expected traits
        var results = new List<EvaluationResult>();
        foreach (var trait in goldenCase.ExpectedTraits)
        {
            var result = EvaluateTraitPresence(response, trait);
            results.Add(result);
        }

        // Assert: all trait evaluations should pass
        Assert.All(results, r => Assert.True(r.IsPass, $"Trait evaluation failed: {r.TraitName}"));
    }

    private static Task<string> InvokeAgentAsync(string userMessage)
    {
        // TODO: Replace with actual agent invocation via the AppHost or HTTP client.
        // This stub returns an empty string to allow the harness to compile and run.
        return Task.FromResult(string.Empty);
    }

    private static EvaluationResult EvaluateTraitPresence(string response, string trait)
    {
        var isPresent = response.Contains(trait, StringComparison.OrdinalIgnoreCase);
        return new EvaluationResult(trait, isPresent);
    }
}

public record GoldenCase
{
    public string Id { get; init; } = string.Empty;
    public string UserMessage { get; init; } = string.Empty;
    public List<string> ExpectedTraits { get; init; } = new();
}

public record EvaluationResult(string TraitName, bool IsPass);

